// Parse technical terms and prepare for research
const response = $input.first().json;
const terms = [];

try {
  const content = JSON.parse(response.choices[0].message.content);
  if (Array.isArray(content)) {
    content.forEach((term, index) => {
      terms.push({
        id: `term_${index + 1}`,
        term: typeof term === 'string' ? term : term.term || term.name,
        category: term.category || 'general',
        priority: term.priority || 'medium',
        timestamp: new Date().toISOString(),
        status: 'pending_research'
      });
    });
  }
} catch (error) {
  // Fallback parsing
  const text = response.choices[0].message.content;
  const matches = text.match(/"([^"]+)"/g) || [];
  matches.forEach((match, index) => {
    terms.push({
      id: `term_${index + 1}`,
      term: match.replace(/"/g, ''),
      category: 'general',
      priority: 'medium',
      timestamp: new Date().toISOString(),
      status: 'pending_research'
    });
  });
}

return terms.map(term => ({ json: term }));

// Create HTML email with embedded images
const reportData = $input.all();
const reportContent = reportData.find(item => item.json.choices)?.json.choices[0].message.content || '';
const imageData = reportData.find(item => item.json.data)?.json.data || [];

const today = new Date().toLocaleDateString('en-US', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

const htmlEmail = `
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Technical Research Report - ${today}</title>
    <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; max-width: 900px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
        .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; border-radius: 12px; margin-bottom: 30px; text-align: center; }
        .header h1 { margin: 0; font-size: 2.5em; font-weight: 300; }
        .header p { margin: 10px 0 0 0; opacity: 0.9; font-size: 1.1em; }
        .content { background: #ffffff; padding: 40px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); margin-bottom: 20px; }
        .image-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 30px 0; }
        .image-placeholder { background: #f8f9fa; border: 2px dashed #dee2e6; padding: 20px; text-align: center; border-radius: 8px; min-height: 200px; display: flex; align-items: center; justify-content: center; flex-direction: column; }
        .image-placeholder img { max-width: 100%; border-radius: 6px; margin-bottom: 10px; }
        .footer { background: #f8f9fa; padding: 30px; border-radius: 12px; text-align: center; color: #6c757d; }
        h1, h2, h3 { color: #2c3e50; margin-top: 30px; }
        h1 { border-bottom: 3px solid #667eea; padding-bottom: 10px; }
        .meta { color: #6c757d; font-size: 0.9em; font-style: italic; }
        .cta { background: #28a745; color: white; padding: 15px 30px; text-decoration: none; border-radius: 6px; display: inline-block; margin: 20px 0; }
        .cta:hover { background: #218838; }
    </style>
</head>
<body>
    <div class="header">
        <h1>🔬 Advanced Technical Research Report</h1>
        <p class="meta">Generated on ${today} | Multi-Agent Research System</p>
    </div>

    <div class="content">
        ${reportContent.replace(/###/g, '<h3>').replace(/##/g, '<h2>').replace(/#/g, '<h1>').replace(/\*\*/g, '<strong>').replace(/\*/g, '<em>').replace(/\n/g, '<br>')}

        <div class="image-grid">
            ${imageData.map((img, index) => `
                <div class="image-placeholder">
                    <img src="${img.url}" alt="Technical Research Diagram ${index + 1}" />
                    <p><strong>Figure ${index + 1}:</strong> Technical visualization for research analysis</p>
                </div>
            `).join('')}
        </div>

        <div style="text-align: center; margin: 30px 0;">
            <a href="#" class="cta">📧 Subscribe to Daily Research Reports</a>
        </div>
    </div>

    <div class="footer">
        <p><strong>About this report:</strong> Generated by advanced multi-agent AI system using headless browsers, content analysis, source validation, and collaborative writing agents.</p>
        <p class="meta">© 2024 AI Business Club - Advanced Research Automation | Powered by QwQ-32B</p>
    </div>
</body>
</html>
`;

return [{ json: { 
  html: htmlEmail, 
  subject: `🔬 Advanced Technical Research Report - ${today}`,
  text: reportContent.replace(/<[^>]*>/g, ''), // Strip HTML for text version
  images: imageData,
  metadata: {
    generated_at: new Date().toISOString(),
    word_count: reportContent.length,
    image_count: imageData.length,
    research_terms: reportData.map(item => item.json.term).filter(Boolean)
  }
}}];

